#!/usr/bin/env node
// md-render-sibling — render markdown to a SIBLING html file with the same name.
// Ported 2026-11-03 from ~/keller-portal/scripts/md-render-sibling.mjs (same style), scoped to
// leland/ in this fork. Images and <video> tags in the markdown work in the html.
//
//   docs/foo.md  →  docs/foo.html  (committed; auto-regenerated by the
//                                   .claude/settings.json hook on every
//                                   Edit/Write touch)
//
// The rendering style is the same dark/full-width/mermaid one we landed on
// 2026-06-18 (see scripts/md-view.mjs header — "100% perfect, gorgeous"). The
// difference is that md-view.mjs writes a one-shot file to /tmp + opens it in
// the browser; md-render-sibling.mjs writes the persistent companion in place,
// silently, so a future reader can open `docs/foo.html` directly without
// running anything.
//
// USAGE:
//   node scripts/md-render-sibling.mjs <file.md>      Render one specific file.
//   node scripts/md-render-sibling.mjs --auto         Find all docs/**/*.md and
//                                                     regenerate any whose
//                                                     sibling .html is missing
//                                                     or older than the .md.
//                                                     Idempotent, fast, safe
//                                                     to run on every tool call
//                                                     (the hook does exactly that).
//   node scripts/md-render-sibling.mjs --all          Force-rerender ALL files
//                                                     under docs/ regardless of
//                                                     mtime (use for backfill).
//   node scripts/md-render-sibling.mjs --check        Print stale files but
//                                                     don't write anything.
//
// ─────────────────────────────────────────────────────────────────────────────
// WHY THIS EXISTS (Leland, 2026-06-23)
// ─────────────────────────────────────────────────────────────────────────────
// docs/ accumulated 65 markdown files; reading them as raw markdown in the
// editor is "crowded, messy, unreadable." The md-view.mjs one-shot approach
// helped for any single doc but required running a command + a /tmp file +
// opening the browser EVERY time. Leland wanted ambient readability: open the
// docs/ folder in any tool, see an .html alongside every .md, click and read.
//
// Made it a STANDING RULE 2026-06-23: every docs/*.md has a sibling .html with
// the same base name, kept current by a .claude/settings.json PostToolUse hook
// that runs this script in --auto mode after any Edit/Write. The .html files
// are committed so other machines (Leland's desktop + laptop, plus FlooringXP
// teammates eventually) see the rendered view without needing to regenerate.
//
// Scope (#4 of Leland's 4 questions, 2026-06-23): docs/**/*.md only. Root
// CLAUDE.md / README.md NOT included (yet).

import { readFileSync, writeFileSync, statSync, existsSync, readdirSync } from "node:fs";
import { basename, join, dirname } from "node:path";

const REPO_ROOT = new URL("../..", import.meta.url).pathname.replace(/\/$/, "");
const DOCS_DIR = join(REPO_ROOT, "leland");

// ─────────────────────────────────────────────────────────────────────────────
// File discovery
// ─────────────────────────────────────────────────────────────────────────────
function listMarkdownsRecursive(dir) {
  const out = [];
  const entries = readdirSync(dir, { withFileTypes: true });
  for (const e of entries) {
    const p = join(dir, e.name);
    if (e.isDirectory()) {
      // Skip well-known noise — node_modules under docs/ would be a bug,
      // but defend just in case.
      if (e.name === "node_modules" || e.name === "tools" || e.name.startsWith(".")) continue;
      out.push(...listMarkdownsRecursive(p));
    } else if (e.isFile() && e.name.endsWith(".md")) {
      out.push(p);
    }
  }
  return out;
}

function siblingHtmlPath(mdPath) {
  return mdPath.replace(/\.md$/, ".html");
}

function isStale(mdPath) {
  const htmlPath = siblingHtmlPath(mdPath);
  if (!existsSync(htmlPath)) return true;
  const mdMs = statSync(mdPath).mtimeMs;
  const htmlMs = statSync(htmlPath).mtimeMs;
  return mdMs > htmlMs;
}

// ─────────────────────────────────────────────────────────────────────────────
// Renderer — same dark/full-width/mermaid style as scripts/md-view.mjs,
// minus the /tmp + browser-open bit. When you tweak this, mirror the change
// to md-view.mjs so the in-browser experience matches the on-disk one.
// ─────────────────────────────────────────────────────────────────────────────
// ─── STATIC RENDER (Leland directive, 2026-08-18 · FXP-144) ──────────────────
// The twin used to ship RAW markdown + CDN <script>s (marked + mermaid) and
// assemble itself in the READER'S browser. Any CDN failure — offline, content
// blocker, strict file:// — left the dark canvas and nothing else: a BLACK
// EMPTY page. Opens fine in VSCode, black outside it; Leland hit it repeatedly.
// Now marked runs HERE at generation time and the twin is finished HTML: no
// scripts, no network, readable forever. Mermaid fences DEGRADE to visible,
// labelled code blocks — a diagram may degrade, a page may not go black. For
// live mermaid rendering use scripts/md-view.mjs locally.
import { createRequire } from "node:module";
const require = createRequire(import.meta.url);
const { marked } = require("marked");

function renderHtml(mdPath, md) {
  const rawTitle = (md.match(/^#\s+(.+)$/m) || [, basename(mdPath)])[1];
  const title = rawTitle.replace(/[*_`#]/g, "").replace(/[<>&]/g, "").trim();
  const head = `<!doctype html>
<html lang="en"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${title}</title>
<style>
  :root{color-scheme:dark}
  *{box-sizing:border-box}
  body{margin:0;background:#0d1117;color:#e6edf3;
       font:17px/1.75 -apple-system,BlinkMacSystemFont,"Segoe UI",Helvetica,Arial,sans-serif}
  .wrap{max-width:1600px;margin:0 auto;padding:48px 80px 160px}
  h1{font-size:2.6em;margin:.2em 0 .4em;border-bottom:1px solid #30363d;padding-bottom:.3em}
  h2{font-size:1.9em;margin:2.4em 0 .6em;border-bottom:1px solid #30363d;padding-bottom:.3em}
  h3{font-size:1.3em;color:#adbac7;margin:1.4em 0 .4em}
  p,li{font-size:1.02em}
  blockquote{border-left:4px solid #2ea043;background:#11261b;margin:1.2em 0;
             padding:.9em 1.3em;border-radius:8px;color:#c9d1d9}
  table{border-collapse:collapse;width:100%;margin:1.2em 0}
  @media (max-width:760px){.wrap{padding:24px 16px 80px} table{display:block;overflow-x:auto} h1{font-size:1.9em} h2{font-size:1.45em}}
  th,td{border:1px solid #30363d;padding:11px 16px;text-align:left}
  th{background:#161b22}
  code{background:#161b22;padding:.15em .45em;border-radius:5px;font-size:.92em}
  pre code{display:block;padding:1em;overflow:auto}
  a{color:#539bf5;text-decoration:none} a:hover{text-decoration:underline}
  hr{border:0;border-top:1px solid #30363d;margin:2.6em 0}
  .mermaid{background:#0d1117;text-align:center;margin:1.8em 0}
  .mermaid svg{max-width:100%;height:auto}
  img,video{max-width:100%;border-radius:8px}
  .md-banner{position:fixed;top:0;right:0;background:#21262d;color:#8b949e;
             padding:6px 12px;font-size:.8em;border-bottom-left-radius:6px;
             border:1px solid #30363d;border-top:0;border-right:0;z-index:99}
  .md-banner a{color:#539bf5}
</style></head><body>
<div class="md-banner">auto-generated from <a href="${basename(mdPath)}">${basename(mdPath)}</a></div>
<div class="wrap" id="content">
`;
  const tail = `
</div></body></html>`;
  // Generation-time render. GFM tables/checklists handled by marked; mermaid
  // fences become labelled code blocks BEFORE parsing so the content is always
  // visible (degraded, never black).
  const withMermaidDegraded = md.replace(
    /```mermaid\n([\s\S]*?)```/g,
    (_, code) =>
      '<div class="mermaid-degraded"><div style="color:#8b949e;font-size:.85em;margin-bottom:.3em">diagram (mermaid source — renders live in scripts/md-view.mjs)</div>\n\n```\n' +
      code +
      "```\n\n</div>"
  );
  // Links between notes go to their .html twins, so a reader clicking through stays in the
  // rendered view. Only relative links: an http(s) URL to a .md file is left alone.
  const body = marked
    .parse(withMermaidDegraded, { gfm: true })
    .replace(/href="(?![a-z]+:)([^"#]+)\.md(#[^"]*)?"/g, 'href="$1.html$2"');
  return head + body + tail;
}

function renderOne(mdPath) {
  const md = readFileSync(mdPath, "utf8");
  const html = renderHtml(mdPath, md);
  writeFileSync(siblingHtmlPath(mdPath), html);
}

// ─────────────────────────────────────────────────────────────────────────────
// CLI dispatch
// ─────────────────────────────────────────────────────────────────────────────
const args = process.argv.slice(2);

if (args.length === 0 || args.includes("--help") || args.includes("-h")) {
  console.error("usage: node leland/tools/md-render-sibling.mjs <file.md> | --auto | --all | --check");
  process.exit(1);
}

if (args.includes("--all") || args.includes("--auto") || args.includes("--check")) {
  const mode = args.includes("--all") ? "all"
            : args.includes("--check") ? "check"
            : "auto";
  // leland/**/*.md, plus the running notes file at the repo root (it lives there because Claude
  // Code loads CLAUDE.local.md from the root).
  const all = listMarkdownsRecursive(DOCS_DIR);
  const notes = join(REPO_ROOT, "CLAUDE.local.md");
  if (existsSync(notes)) all.push(notes);
  let touched = 0, skipped = 0;
  for (const mdPath of all) {
    const stale = isStale(mdPath);
    if (mode === "all" || (mode === "auto" && stale) || (mode === "check" && stale)) {
      if (mode === "check") {
        console.log("stale:", mdPath.replace(REPO_ROOT + "/", ""));
        touched++;
      } else {
        renderOne(mdPath);
        touched++;
      }
    } else {
      skipped++;
    }
  }
  if (mode === "check") {
    console.log(`${touched} stale, ${skipped} up-to-date, ${all.length} total`);
    process.exit(touched > 0 ? 1 : 0);
  } else {
    console.log(`${mode}: rendered ${touched}, skipped ${skipped}, total ${all.length}`);
  }
} else {
  // Single-file mode: render the named .md file (e.g. docs/foo.md → docs/foo.html)
  const mdPath = args[0].startsWith("/") ? args[0] : join(process.cwd(), args[0]);
  if (!mdPath.endsWith(".md")) {
    console.error(`expected a .md file, got: ${mdPath}`);
    process.exit(1);
  }
  if (!existsSync(mdPath)) {
    console.error(`not found: ${mdPath}`);
    process.exit(1);
  }
  renderOne(mdPath);
  console.log(`wrote ${siblingHtmlPath(mdPath)}`);
}
